import { Avatar, Box, Button, Card, CardContent, CardHeader, CardMedia, Grid, LinearProgress, Typography } from "@mui/material";
import { VICTIMS } from "./victims";
import { HUMEUR_LABEL } from "./hooks";





const VictimCard = ({state})=>{
   
    return <Box>
       <Card>
        <CardHeader title={state.victim.name} subheader={state.victim.phaseActuelle}></CardHeader>
         <CardMedia
        component="img"
        height="194"
        image={state.victim.image}
        alt="Paella dish"
      />
        <CardContent>
          <Box textAlign="center" mb={2}>
                {/*  */}
                <Typography variant="h5" sx={{ mb: 1, fontWeight: 'bold' }}>
                  {state.victim.name}
                </Typography>
                <Typography variant="subtitle1" color="textSecondary">
                  Humeur : {state.victim.humeur}
                </Typography>
              </Box>

              {/* Jauges Amour / Excitation */}
              <Box mt={3}>
                <JaugeBar 
                  label="Jauge d'Amour" 
                  value={state.jauges.amour} 
                  color="primary" 
                />
                <JaugeBar 
                  label="Jauge d'Excitation" 
                  value={state.jauges.excitation} 
                  color="secondary" 
                />
              </Box>
        </CardContent>
    </Card>

     </Box>
}

const JaugeBar = ({ label, value, color }) => (
    <Box sx={{ mb: 1 }}>
      <Typography variant="body2" color="textSecondary" sx={{ mb: 0.5, fontWeight: 'bold' }}>
        {label} ({value}%)
      </Typography>
      <LinearProgress
        variant="determinate" 
        value={value} 
        color={color} 
        sx={{ height: 10, borderRadius: 5 }} 
      />
    </Box>
  );
export default VictimCard;


export const Feedback = ({state})=>{
        {/* Zone de Feedback / Narration */}
  return        <Card raised sx={{ mt: 3, p: 2, backgroundColor: '#f5f5f5' }}>
            <Typography variant="body1" sx={{ fontStyle: 'italic', color: '#555' }}>
              **Feedback de {state.victim.name} :**
            </Typography>
            <Typography variant="body1">
              {state.victim.lastFeedback}
            </Typography>
          </Card>
}

// src/dragueur/VictimSelector.jsx

export const VictimSelector = ({ onSelectVictim }) => {
  return (
    <Box sx={{ p: 4, textAlign: 'center' }}>
      <Typography variant="h3" gutterBottom>
        Choisissez Votre Cible pour le SimuDragueur
      </Typography>
      <Typography variant="h6" color="textSecondary" sx={{ mb: 4 }}>
        Chaque victime a ses propres règles secrètes et ses faiblesses.
      </Typography>

      <Grid container spacing={4} justifyContent="center">
        {VICTIMS.map((victim, index) => (
          <Grid item xs={12} sm={6} md={3} key={index}>
            <Card raised sx={{ height: '100%', display: 'flex', flexDirection: 'column', transition: '0.3s', '&:hover': { boxShadow: 6 } }}>
              
              <CardMedia
                component="img"
                height="200"
                image={victim.image || 'https://via.placeholder.com/300x200?text=Victim'}
                alt={victim.name}
              />
              
              <CardContent sx={{ flexGrow: 1 }}>
                <Typography gutterBottom variant="h5" component="div">
                  {victim.name}
                </Typography>
                <Typography variant="body2" color="text.secondary">
                  *Statut : {HUMEUR_LABEL[victim.humeur]}*
                </Typography>
              </CardContent>

              <Box sx={{ p: 2 }}>
                <Button 
                  variant="contained" 
                  color="primary" 
                  fullWidth 
                  onClick={() => onSelectVictim(victim)}
                >
                   Draguer  {victim.name}
                </Button>
              </Box>
            </Card>
          </Grid>
        ))}
      </Grid>
    </Box>
  );
};

 