import { Box, Button, Card, CardContent, Grid, Typography } from "@mui/material";
import FavoriteIcon from "@mui/icons-material/Favorite";        // GENTIL
import WhatshotIcon from "@mui/icons-material/Whatshot";        // VULGAIRE (piquant/borderline)
import EmojiEventsIcon from "@mui/icons-material/EmojiEvents";  // MACHO (ego & frime)
import ThumbUpIcon from "@mui/icons-material/ThumbUp";          // CONFIANT
import HandshakeIcon from "@mui/icons-material/Handshake";      // RESPECT
import HelpIcon from "@mui/icons-material/Help";     
import { PHASES_DATA } from "./phrases";
const getTonIcon = (ton) => {
  switch (ton) {
    case "GENTIL":
      return <FavoriteIcon sx={{ mr: 1, color: "#ff80ab" }} />;
    case "VULGAIRE":
      return <WhatshotIcon sx={{ mr: 1, color: "#f44336" }} />;
    case "MACHO":
      return <EmojiEventsIcon sx={{ mr: 1, color: "#ffc107" }} />;
    case "CONFIANT":
      return <ThumbUpIcon sx={{ mr: 1, color: "#4caf50" }} />;
    case "RESPECT":
      return <HandshakeIcon sx={{ mr: 1, color: "#64b5f6" }} />;
    default:
      return <HelpIcon sx={{ mr: 1 }} />;
  }
};

const ChoicePanel = ({gameState, handleChoice})=>{
    
const allChoices = PHASES_DATA[gameState.victim.phaseActuelle]
    return <Box>
       <Typography variant="h5" gutterBottom sx={{ mb: 2 }}>
            ⚡ (Phase : {gameState.victim.phaseActuelle}) Lieu : {gameState.reglagesGlobaux.lieuActuel}
          </Typography>
          <Grid container spacing={2}>
            {allChoices.map((choice, index) => {
            if(!choice.condition(gameState))
                return null;
            else
            return  <Grid item xs={12} sm={6} key={index}>
                <Button
                  variant="contained"
                  fullWidth
                  size="large"
                  onClick={() => handleChoice(choice)}
                  sx={getChoiceStyle(choice)}
                >
                   {getTonIcon(choice.stimulus?.ton)}
                  {choice.text}
                </Button>
              </Grid>
})}
          </Grid>
    </Box>
}

export default ChoicePanel;

const getChoiceStyle = (choice) => {
  const base = {
    py: 2,
    textAlign: 'left',
    justifyContent: 'flex-start',
    textTransform: 'none',
    color: 'white'
  };

  // Distinction par action
  if (choice.action?.startsWith("DIAL_")) {
    return {
      ...base,
      background: 'linear-gradient(45deg, #9c27b0 30%, #d500f9 90%)',
      boxShadow: '0 3px 5px 2px rgba(156, 39, 176, .3)',
      '&:hover': {
        background: 'linear-gradient(45deg, #d500f9 30%, #9c27b0 90%)',
      }
    };
  }

  if (choice.action?.startsWith("GOTO_")) {
    return {
      ...base,
      background: 'linear-gradient(45deg, #43a047 30%, #66bb6a 90%)',
      boxShadow: '0 3px 5px 2px rgba(76, 175, 80, .3)',
      '&:hover': {
        background: 'linear-gradient(45deg, #66bb6a 30%, #43a047 90%)',
      }
    };
  }

  // Distinction par stimulus.type
  switch (choice.stimulus?.type) {
    case "INTERET":
      return {
        ...base,
        background: 'linear-gradient(45deg, #1c75c8 30%, #4facfe 90%)',
        boxShadow: '0 3px 5px 2px rgba(33, 203, 243, .3)',
        '&:hover': {
          background: 'linear-gradient(45deg, #4facfe 30%, #1c75c8 90%)',
        }
      };
    case "CONTACT":
      return {
        ...base,
        background: 'linear-gradient(45deg, #e53935 30%, #ff7043 90%)',
        boxShadow: '0 3px 5px 2px rgba(255, 87, 34, .3)',
        '&:hover': {
          background: 'linear-gradient(45deg, #ff7043 30%, #e53935 90%)',
        }
      };
    case "COMPLIMENT":
      return {
        ...base,
        background: 'linear-gradient(45deg, #2fad13ff 30%, #569e2cff 90%)',
        boxShadow: '0 3px 5px 2px rgba(52, 255, 34, 0.3)',
        '&:hover': {
          background: 'linear-gradient(45deg, #4fc136ff 30%, #26b114ff 90%)',
        }
      };
    case "BLAGUE":
      return {
        ...base,
        background: 'linear-gradient(45deg, #aeae2aff 30%, #d7d735ff 90%)',
        boxShadow: '0 3px 5px 2px rgba(229, 255, 34, 0.3)',
        '&:hover': {
          background: 'linear-gradient(45deg, #cccf34ff 30%, #dce535ff 90%)',
        }
      };
    case "INVITATION":
      return {
        ...base,
        background: 'linear-gradient(45deg, #607d8b 30%, #90a4ae 90%)',
        boxShadow: '0 3px 5px 2px rgba(96, 125, 139, .3)',
        '&:hover': {
          background: 'linear-gradient(45deg, #90a4ae 30%, #607d8b 90%)',
        }
      };
    default:
      return {
        ...base,
        background: 'linear-gradient(45deg, #757575 30%, #bdbdbd 90%)',
        boxShadow: '0 3px 5px 2px rgba(117, 117, 117, .3)',
        '&:hover': {
          background: 'linear-gradient(45deg, #bdbdbd 30%, #757575 90%)',
        }
      };
  }
};
