import React from 'react';
import { Dialog, DialogTitle, DialogContent, Button, Box, Typography } from '@mui/material';

// Mappage des actions vers les options et les effets
const DIALOG_ACTIONS = {
  toucherSousTable: {
    title: "Comment allez-vous procéder au contact ?",
    options: [
      { label: "Du pied (Subtil)", stimulus: { type: "CONTACT", ton: "GENTIL", cible: "corps" } },
      { label: "Avec la main (Direct)", stimulus: { type: "CONTACT", ton: "CONFIANT", cible: "main" } },
      { label: "Sous la jupe (dans la culotte)", stimulus: { type: "CONTACT", ton: "VULGAIRE", cible: "chatte" } },
    ]
  },
  contactMain:{
    title:"Manoeuvre de drague",
    options:[
      {label:"En frolant le dos de la main avec vos doigts", stimulus:{ type: "CONTACT", ton: "CONFIANT", cible: "main" }},
      {label:"En faisant en baise-main au passage", stimulus:{ type: "CONTACT", ton: "RESPECT", cible: "main" }},
      {label:"En evitant tout contact", stimulus:{ type: "INTERET", ton: "GENTIL", cible: "main" }},
      {label:"En caressant sensuellement avec un clin d'oeil", stimulus:{ type: "CONTACT", ton: "MACHO", cible: "main" }},
      
    ]
  },
  mainAuCul:{
    title:"Vous matez son cul",
    options:[
      {label:"Vous imaginez a quoi il ressemblerait sans la jupe", stimulus:{ type: "INTERET", ton: "CONFIANT", cible: "cul" }},
      {label:"Une bonne claque au cul, ca reveille", stimulus:{ type: "CONTACT", ton: "MACHO", cible: "cul" }},
      {label:"Vous la pelotez bien entre les fesses", stimulus:{ type: "CONTACT", ton: "VULGAIRE", cible: "cul" }},
      {label:"Vous lui caressez sensuellement les hanches", stimulus:{ type: "CONTACT", ton: "CONFIANT", cible: "cul" }},
      
    ]
  },
  toucherVisage:{
 title:"Vous passez la main sur son visage",
    options:[
      {label:"Vous l'effleurez en la regardant droit dans les yeux", stimulus:{ type: "INTERET", ton: "CONFIANT", cible: "visage" }},
      {label:"Vous lui caressez la joue", stimulus:{ type: "CONTACT", ton: "GENTIL", cible: "visage" }},
      {label:"Vous lui caressez les levres", stimulus:{ type: "CONTACT", ton: "MACHO", cible: "visage" }},
      {label:"Vous lui caressez les levres et inserer votre doigt dans sa bouche pour voir si elle suce bien", stimulus:{ type: "CONTACT", ton: "VULGAIRE", cible: "visage" }},
      
    ]
  }
  // Ajoutez d'autres actions ici (ex: offrirCadeau, etc.)
};

const DragueurDialog = ({ actionName, onActionSelect, open, handleClose }) => {
  if (!open || !DIALOG_ACTIONS[actionName]) return null;

  const actionData = DIALOG_ACTIONS[actionName];

  return (
    <Dialog open={open} onClose={handleClose} maxWidth="sm" fullWidth>
      <DialogTitle>{actionData.title}</DialogTitle>
      <DialogContent>
        <Typography variant="body1" sx={{ mb: 3 }}>
          Choisissez votre niveau d'audace. (Chaque option aura un effet différent sur les jauges.)
        </Typography>
        <Box sx={{ display: 'flex', flexDirection: 'column', gap: 2 }}>
          {actionData.options.map((option, index) => (
            <Button
              key={index}
              variant="contained"
              color="primary"
              size="large"
              onClick={() => onActionSelect(option.stimulus)}
            >
              {option.label}
            </Button>
          ))}
        </Box>
      </DialogContent>
    </Dialog>
  );
};
export default DragueurDialog;

