import React, { createContext, useContext, useState } from "react";

import { Box } from "@mui/material";
 import VictimCard, { Feedback, VictimSelector } from "./VictimCard";
 import ChoicePanel from "./ChoicePanel";
import { VICTIMS } from "./victims";
import { handleChoiceClick } from "./hooks";
import DragueurDialog from "./DragueurAction";



const DragueurContext = createContext();

export const useDragueur = () => useContext(DragueurContext);

const SimuDragueur = () => {
  // L'état initial est null, ce qui force l'affichage du sélecteur
  const [selectedVictim, setSelectedVictim] = useState(null);

  if (!selectedVictim) {
    // Si aucune victime n'est sélectionnée, affiche le sélecteur
    return <VictimSelector onSelectVictim={setSelectedVictim} />;
  }


  // On renvoie le composant principal en lui passant l'état initial de la victime
  return <SimuDragueurCore selectedVictim={selectedVictim} />;
};
const SimuDragueurCore = ({selectedVictim}) => {
const [activeAction, setActiveAction] = useState(null);
    const [state, setState] = useState({
  // Profil de la cible
  victim: selectedVictim,
  // Le Score du Joueur
  jauges: {
    amour: 10,       // Échelle 0-100
    excitation: 5,   // Échelle 0-100
  },
  // Les réglages permanents (style vestimentaire, etc.)
  reglagesGlobaux: {
    skills:[],//dirtyTalk,touchy,naked,hard,cool, costard, rebeu, clodo, flashy
    lieuActuel: 'rue' // rue, bar, restau, cine, chezElle, chezMoi
  }
});

const handleChoice = choice=>{
   const newState = handleChoiceClick(choice, state);
   if(choice.action!=null&&choice.action.startsWith('GOTO'))
    newState.lieuActuel=choice.action.substring(5,choice.action.length);
  else if (choice.action && choice.action.startsWith('DIAL')) {
       // DIAL: ouverture du dialogue d'action
       setActiveAction(choice.action.substring(5)); // Ex: 'DIAL_toucherSousTable' devient 'toucherSousTable'
   }
   setState(newState);
}
const handleDialogAction = (stimulusResult) => {
    setActiveAction(null); // Ferme le dialogue
    // Logique future : Utiliser stimulusResult pour faire un autre handleChoiceClick
    const newState = handleChoiceClick({ stimulus: stimulusResult }, state); 
    setState(newState);
};
  return  <Box sx={{display:'flex'}}>
        <VictimCard state={state}/>
        <Box sx={{display:'flex', flexDirection:'column', gap:3,m:2}}>
            <Feedback state={state}/>
            <ChoicePanel gameState={state} handleChoice={handleChoice}/>
        </Box>
        <DragueurDialog 
  actionName={activeAction} 
  onActionSelect={handleDialogAction} 
  open={activeAction !== null}
  handleClose={() => setActiveAction(null)}
/>
     </Box>
   
  
};
export default SimuDragueur;


