

export const handleChoiceClick = (choice, state) => {
    const stimulus = choice.stimulus;
    const { jauges, reglagesGlobaux ,victim: victimProfile} = state;

    let netAmour = 0;
    let netExcitation = 0;
    const humeur=victimProfile.humeur;
    
    // 1. CALCUL DE L'EFFET NET (Cœur de l'IA)
    // ----------------------------------------
    
    // La victime évalue le stimulus selon toutes ses règles
    victimProfile.reglesReaction.forEach(regle => {
        
      if (regle.condition(stimulus, reglagesGlobaux)) {
            
            // 2. Laisse la règle elle-même calculer son impact,
            //    en tenant compte du contexte global (reglagesGlobaux).
            const effets = regle.calculEffet(stimulus, reglagesGlobaux, humeur);
            
            netAmour += effets.amour ?? 0;
            netExcitation += effets.excitation ?? 0;
        }
    });

    // 2. MISE À JOUR DES JAUGES ET DU SCORE
    // -------------------------------------
    
    let newAmour = Math.min(100, Math.max(0, jauges.amour + netAmour));
    let newExcitation = Math.min(100, Math.max(0, jauges.excitation + netExcitation));
    const newNetSeduction = newAmour + newExcitation;

    // 3. VÉRIFICATION DE LA TRANSITION DE PHASE
    // -----------------------------------------
    
    let newPhase = state.victim.phaseActuelle;
    if (newNetSeduction >= 150) {
        newPhase = 'CaMord';
    } else if (newNetSeduction >= 100) {
        newPhase = 'PriseEnMain';
    } else if (newNetSeduction >= 50) {
        newPhase = 'BrisageDeGlace';
    } else if (newNetSeduction < 50 && state.victim.phaseActuelle !== 'Abordage') {
        // Optionnel : Retours en arrière si le score chute trop bas
        newPhase = 'Abordage'; 
    }

    // 4. DÉTERMINATION DU FEEDBACK NARRATIF (0 à 4)
    // --------------------------------------------
    
    const totalEffect = netAmour + netExcitation;
    let feedbackScale = 2; // Par défaut : Neutre

    if (totalEffect >= 16) {
        feedbackScale = 4; // Positif Fort
    } else if (totalEffect >= 6) {
        feedbackScale = 3; // Positif Léger
    } else if (totalEffect <= -16) {
        feedbackScale = 0; // Négatif Fort
    } else if (totalEffect <= -6) {
        feedbackScale = 1; // Négatif Léger
    }
    let feedbackText=null;
    if(choice.customResponse!=null)
        feedbackText = choice.customResponse(feedbackScale);
    else{
        const fdb = victimProfile.feedbackLexicon[feedbackScale];
        feedbackText = typeof fdb === 'function' ?fdb(stimulus):fdb;
    }
    const newGlobal = {...state.reglagesGlobaux};
    if(choice.unlock!=null && !newGlobal.skills.includes(choice.unlock)){
        newGlobal.skills.push(choice.unlock);
    }


    // 5. CONSTRUCTION DU NOUVEL ÉTAT
    // ------------------------------
const  humeurId=determineNewHumeur(newAmour,newExcitation);
    return {
        reglagesGlobaux:newGlobal,
        jauges: { amour: newAmour, excitation: newExcitation },
        victim: { 
            ...state.victim, 
            humeur:humeurId,
            phaseActuelle: newPhase,
            lastFeedback: feedbackText, // On stocke le feedback pour l'affichage
            lastTotalEffect: totalEffect
        },
        // Logique pour gérer choice.unlock et choice.action (à implémenter via un reducer)
    };
};

/**
 * Index,Nom de l'Humeur,Caractérisation pour l'IA,Effet sur le Gameplay (Règles d'affichage)
0,Méprisante,Négatif Fort. Rejet total.,Débloque les phrases d'excuses ou les défis. Cache les phrases douces.
1,Neutre,"Défaut / Froid. Observatrice, distante.",Seules les phrases d'Abordage ou de Détection sont disponibles.
2,Méfiance,Négatif Léger. Elle soupçonne vos intentions.,Débloque les phrases pour Rassurer ou Atténuer le ton.
3,Intéressée,Positif Léger. Le jeu fonctionne.,Débloque les phrases de Mise en Confiance et les Questions Personnelles.
4,Fascinée,Positif Fort. Elle est sous le charme (Amour élevé).,Débloque les actions de Relation Durable ou de Future Projection.
5,Excité,Positif Fort. Elle est en feu (Excitation élevée).,Débloque les Sous-entendus et les Actions Hardcore.
 */
export const HUMEUR_LABEL=['Méprisante','Neutre','Curieuse','Intéressée','Fascinée', 'Excité'];
const determineNewHumeur = (newAmour, newExcitation) => {
    const totalScore = newAmour + newExcitation;
    const diff = newAmour - newExcitation; // Balance : Positif = Amour > Excit. / Négatif = Excit. > Amour

    if (totalScore < 10) {
        return 0; // Très bas score
    }
    
    if (totalScore < 50) {
        // En phase d'abordage, l'humeur est neutre ou méfiante
        return diff < -15 ? 2 : 1;
    }

    if (totalScore >= 50) {
        // En phase avancée, l'humeur devient positive
        if (diff > 30) {
            return 4; // Beaucoup plus d'Amour que d'Excitation
        } else if (diff < -30) {
            return 5; // Beaucoup plus d'Excitation que d'Amour
        } else if (totalScore >= 100) {
             return 3; // Avancement général
        }
    }

    return 'Neutre'; // Fallback
};